import './App.css';

function App() {
  const name = "John";
  const age = 20;
  const city = "New York";
  const country = "USA";
  const email = "john@gmail.com";
  const phone = "1234567890";
  const address = "123 Main St, New York, NY 10001";

  return (
    <div className="App">
      <header className="App-header">
        <h1>Hello World</h1>
        <p>{name}</p>
        <p>Age: {age}</p>
        <p>City {city}, {country}</p>
        <p>{email}</p>
        <p>{phone}</p>
        <p>{address}</p>
      </header>
    </div>
  );
}

export default App;
